SELECT '1. 已加 CHECK venue_source_overrides_month_start（生效日必須是 1 日）' AS item, EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'venue_source_overrides_month_start' AND conrelid = 'public.teamcommission_venue_revenue_source_overrides'::regclass) AS ok
UNION ALL SELECT '2. 政策數仍為 4', (SELECT count(*) FROM pg_policy WHERE polrelid = 'public.teamcommission_venue_revenue_source_overrides'::regclass) = 4
UNION ALL SELECT '3. insert 政策含台北月初限制', (SELECT pg_get_expr(polwithcheck, polrelid) FROM pg_policy WHERE polrelid = 'public.teamcommission_venue_revenue_source_overrides'::regclass AND polname = 'venue_source_overrides_insert') LIKE '%Asia/Taipei%'
UNION ALL SELECT '4. update 政策 USING／WITH CHECK 皆含台北月初限制', (SELECT pg_get_expr(polqual, polrelid) LIKE '%Asia/Taipei%' AND pg_get_expr(polwithcheck, polrelid) LIKE '%Asia/Taipei%' FROM pg_policy WHERE polrelid = 'public.teamcommission_venue_revenue_source_overrides'::regclass AND polname = 'venue_source_overrides_update')
UNION ALL SELECT '5. delete 政策含台北日期限制', (SELECT pg_get_expr(polqual, polrelid) FROM pg_policy WHERE polrelid = 'public.teamcommission_venue_revenue_source_overrides'::regclass AND polname = 'venue_source_overrides_delete') LIKE '%Asia/Taipei%';
